{
  "name": "tanstack-query-todo",
  "version": "1.0.0",
  "description": "TanStack Query Todo List Application",
  "main": "server.js",
  "scripts": {
    "build": "vite build",
    "start": "vite build && node server.js"
  },
  "dependencies": {
    "@tanstack/react-query": "^5.0.0",
    "express": "^4.19.2",
    "react": "^18.3.1",
    "react-dom": "^18.3.1"
  },
  "devDependencies": {
    "@vitejs/plugin-react": "^4.3.1",
    "vite": "^5.3.1"
  }
}

import { defineConfig } from 'vite';
import react from '@vitejs/plugin-react';

export default defineConfig({
  plugins: [react()],
  build: {
    outDir: 'dist',
    emptyOutDir: true,
  },
});

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App.jsx';

ReactDOM.createRoot(document.getElementById('root')).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import { useState } from 'react';
import {
  QueryClient,
  QueryClientProvider,
  useQuery,
  useMutation,
  useQueryClient,
} from '@tanstack/react-query';

const queryClient = new QueryClient();

function TodoApp() {
  const [text, setText] = useState('');
  const queryClient = useQueryClient();

  // Fetch todos
  const { data: todos = [], isLoading, error } = useQuery({
    queryKey: ['todos'],
    queryFn: async () => {
      const response = await fetch('/api/todos');
      if (!response.ok) {
        throw new Error('Network response was not ok');
      }
      return response.json();
    },
  });

  // Create todo mutation
  const mutation = useMutation({
    mutationFn: async (newTodoText) => {
      const response = await fetch('/api/todos', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({ text: newTodoText }),
      });
      if (!response.ok) {
        throw new Error('Failed to create todo');
      }
      return response.json();
    },
    onSuccess: () => {
      // Invalidate and refetch
      queryClient.invalidateQueries({ queryKey: ['todos'] });
      setText('');
    },
  });

  const handleSubmit = (e) => {
    e.preventDefault();
    if (!text.trim()) return;
    mutation.mutate(text);
  };

  return (
    <div style={{ padding: '20px', fontFamily: 'sans-serif' }}>
      <h1>Todo List</h1>

      <form onSubmit={handleSubmit}>
        <input
          id="todo-input"
          type="text"
          value={text}
          onChange={(e) => setText(e.target.value)}
          placeholder="Enter todo..."
          disabled={mutation.isPending}
        />
        <button id="todo-submit" type="submit" disabled={mutation.isPending}>
          {mutation.isPending ? 'Adding...' : 'Add Todo'}
        </button>
      </form>

      {isLoading && <p>Loading todos...</p>}
      {error && <p style={{ color: 'red' }}>Error: {error.message}</p>}

      <ul id="todo-list">
        {todos.map((todo) => (
          <li key={todo.id}>{todo.text}</li>
        ))}
      </ul>
    </div>
  );
}

export default function App() {
  return (
    <QueryClientProvider client={queryClient}>
      <TodoApp />
    </QueryClientProvider>
  );
}

const express = require('express');
const path = require('path');
const app = express();
const PORT = process.env.PORT || 4821;

app.use(express.json());

// Keep the backend state in-memory for simplicity
let todos = [];
let nextId = 1;

// GET /api/todos
app.get('/api/todos', (req, res) => {
  res.status(200).json(todos);
});

// POST /api/todos
app.post('/api/todos', (req, res) => {
  const { text } = req.body;
  if (typeof text !== 'string') {
    return res.status(400).json({ error: 'Text must be a string' });
  }
  const newTodo = {
    id: nextId++,
    text,
    completed: false
  };
  todos.push(newTodo);
  res.status(201).json(newTodo);
});

// Serve static files from the Vite build output
app.use(express.static(path.join(__dirname, 'dist')));

// Fallback for SPA (Single Page Application)
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'dist', 'index.html'));
});

app.listen(PORT, () => {
  console.log(`Server is running on port ${PORT}`);
});
